const escapeHTML=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const glossaryTerms=[
{term:'Аркан',definition:'Число от 1 до 22 в системе «Матрица судьбы». Его используют как символическую тему для размышления о характере и жизненных сценариях.'},
{term:'Асцендент',definition:'Знак, который поднимался над восточным горизонтом в момент рождения. В астрологии его связывают с первым впечатлением, манерой проявляться и начинать дела.'},
{term:'Аспект',definition:'Угловая связь между двумя планетами. Она показывает, насколько легко или напряжённо сочетаются темы этих планет.'},
{term:'Астрологический дом',definition:'Одна из 12 областей натальной карты. Каждый дом связывают с определённой сферой жизни: отношениями, работой, домом, деньгами и другими.'},
{term:'Десцендент',definition:'Точка напротив Асцендента. В астрологии её связывают с партнёрством и качествами, которые человек ищет или замечает в других.'},
{term:'Дома в знаках',definition:'Положение начала каждого дома в знаке зодиака. Оно описывает привычный стиль поведения в соответствующей сфере жизни.'},
{term:'Знак зодиака',definition:'Один из 12 равных секторов зодиакального круга. Знак описывает стиль, в котором проявляется планета или дом.'},
{term:'Кармический хвост',definition:'Термин из «Матрицы судьбы» для набора повторяющихся тем и привычных сценариев. Это часть символической интерпретации, а не научный показатель.'},
{term:'Квадрат',definition:'Напряжённый аспект около 90°. Его трактуют как внутреннее противоречие, которое требует действий, практики и поиска баланса.'},
{term:'Куспид',definition:'Начальная граница астрологического дома. Знак на куспиде описывает стиль проявления этой сферы жизни.'},
{term:'Линия денег',definition:'Символическая комбинация чисел в «Матрице судьбы», которую связывают с отношением к заработку, расходам и материальным решениям.'},
{term:'Линия отношений',definition:'Символическая комбинация чисел в «Матрице судьбы», которую связывают с близостью, ожиданиями и привычным поведением в паре.'},
{term:'Лунный узел',definition:'Расчётная точка пересечения орбиты Луны с эклиптикой. В астрологии Северный узел связывают с новым опытом и направлением развития.'},
{term:'Матрица судьбы',definition:'Нумерологическая система интерпретации даты рождения через числа от 1 до 22. Она подходит для саморефлексии, но не является научным методом.'},
{term:'Натальная карта',definition:'Схема положения планет, домов и углов на момент и в месте рождения человека.'},
{term:'Оппозиция',definition:'Аспект около 180°. Его трактуют как два противоположных полюса, между которыми важно находить равновесие.'},
{term:'Орбис',definition:'Допустимое отклонение аспекта от точного угла. Чем меньше орбис, тем точнее связь между планетами.'},
{term:'Планета',definition:'В астрологической интерпретации планета обозначает отдельную психологическую функцию: эмоции, мышление, волю, близость или способ действовать.'},
{term:'Планеты в домах',definition:'Показывают, в каких жизненных сферах особенно заметно проявляются темы каждой планеты.'},
{term:'Планеты в знаках',definition:'Показывают стиль, в котором проявляются темы каждой планеты: эмоции, мышление, воля, отношения и действия.'},
{term:'Предназначение',definition:'В «Матрице судьбы» так называют символическую тему развития. Это не заранее заданная судьба, а повод подумать о целях и сильных сторонах.'},
{term:'Ретроградность',definition:'Видимое обратное движение планеты с Земли. В астрологии его связывают с более внутренним или пересматривающим способом проявления темы планеты.'},
{term:'Секстиль',definition:'Гармоничный аспект около 60°. Его трактуют как возможность, которая раскрывается через инициативу и практику.'},
{term:'Середина неба (MC)',definition:'Верхняя точка натальной карты. В астрологии её связывают с карьерой, общественной ролью и долгосрочным направлением.'},
{term:'Синастрия',definition:'Сравнение двух натальных карт. Оно показывает поддерживающие и напряжённые связи между планетами двух людей.'},
{term:'Соединение',definition:'Аспект около 0°, когда две планеты находятся рядом. Их темы усиливаются и действуют вместе.'},
{term:'Транзит',definition:'Текущее положение планеты по отношению к натальной карте. На этой связи строится персональный прогноз на день.'},
{term:'Тригон',definition:'Гармоничный аспект около 120°. Его трактуют как естественную поддержку и способность, которая обычно даётся легче.'},
{term:'Центральное число',definition:'Основное число в «Матрице судьбы», рассчитанное из даты рождения. Оно задаёт главную символическую тему интерпретации.'},
{term:'Энергия аркана',definition:'Образное название качеств и сценариев, связанных с конкретным числом в «Матрице судьбы».'}
].sort((a,b)=>a.term.localeCompare(b.term,'ru'));
function normalizeGlossaryQuery(value){return value.trim().toLocaleLowerCase('ru-RU').replace(/ё/g,'е')}
function renderGlossary(query=''){const needle=normalizeGlossaryQuery(query),items=needle?glossaryTerms.filter(item=>normalizeGlossaryQuery(`${item.term} ${item.definition}`).includes(needle)):glossaryTerms;const grouped=items.reduce((map,item)=>{const key=item.term[0];map.set(key,[...(map.get(key)||[]),item]);return map},new Map());$('#glossary-list').innerHTML=[...grouped].map(([letter,group],index)=>`<details class="glossary-group" ${(needle||index===0)?'open':''}><summary><strong>${letter}</strong><span>${group.length}</span></summary><div>${group.map(item=>`<article><strong>${escapeHTML(item.term)}</strong><span>${escapeHTML(item.definition)}</span></article>`).join('')}</div></details>`).join('');$('#glossary-empty').hidden=items.length>0}
const glossaryQuery=$('#glossary-query');glossaryQuery.oninput=()=>renderGlossary(glossaryQuery.value);renderGlossary();
